$normalise=function($item){$type=strtolower($item['type']??'');if(!$type){$title=strtolower($item['title']??'');$type=preg_match('/^(feat|add|new)/',$title)?'added':(preg_match('/^(fix|bugfix|repair)/',$title)?'fixed':(preg_match('/^(remove|delete)/',$title)?'removed':(preg_match('/^(perf|optimi)/',$title)?'improved':(preg_match('/^security/',$title)?'security':'changed'))));}return array_merge($item,['type'=>$type]);};
$items=collect($changelog??[])->map($normalise);
