<script>(function(){var url=@json(route('admin.updates.status')),seen=@json(($state['status']??'')==='running'),reload=false;function setButton(b,a,r){if(!b)return;var i=b.querySelector('i'),t=document.getElementById('nodexa-update-button-text');b.disabled=r||!a;if(i)i.className=r?'fa fa-spinner fa-spin':(a?'fa fa-cloud-download':'fa fa-check');if(t)t.textContent=r?'Installerer…':(a?'Opdater nu':'Opdateret')}function poll(){fetch(url,{headers:{Accept:'application/json'},credentials:'same-origin'}).then(r=>r.json()).then(d=>{var s=d.state||{},a=d.update_available===true,b=document.getElementById('nodexa-update-button'),title=document.getElementById('nxTitle'),msg=document.getElementById('nxMessage'),status=document.getElementById('nxStatusText'),progress=document.getElementById('nxProgress'),icon=document.querySelector('#nxUpdateIcon i');if(s.status==='running'){seen=true;title.textContent='Installerer opdatering…';msg.textContent=s.message||'Opdateringen installeres automatisk.';status.textContent='Opdaterer nu';progress.classList.add('show');icon.className='fa fa-refresh fa-spin';setButton(b,a,true);return}progress.classList.remove('show');if(s.status==='failed'&&seen){title.textContent='Opdateringen fejlede';msg.textContent=s.message||'Opdateringen kunne ikke gennemføres.';status.textContent='Opdatering fejlede';icon.className='fa fa-times';setButton(b,a,false);return}if(s.status==='success'&&seen){title.textContent='Nodexa er opdateret';msg.textContent='Den nye version er installeret.';status.textContent='Systemet er opdateret';icon.className='fa fa-check';setButton(b,false,false);if(!reload){reload=true;setTimeout(()=>location.reload(),2200)}return}title.textContent=a?'Ny Nodexa-opdatering':'Nodexa er opdateret';msg.textContent=a?'En nyere version er klar til installation.':'Du bruger allerede den nyeste tilgængelige version.';status.textContent=a?'Opdatering tilgængelig':'Systemet er opdateret';icon.className=a?'fa fa-cloud-download':'fa fa-check';setButton(b,a,false)}).catch(()=>{})}setInterval(poll,2200);poll()})();</script>
